using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.Rendering;

namespace SpellGame.Game
{
    /// <summary>
    /// The shared look of every in-room screen: one crystal (ice blue) accent plus white text on translucent crystal
    /// panels, crisp TextMeshPro text (Rajdhani), and P1 red / P2 blue only for player names and markers.
    /// All UI colours live in the palette below, so a different accent is a one-line change.
    /// Fonts and materials come from <see cref="UiTheme"/> (Resources), generated by SpellGame → Rebuild Main Scene.
    /// </summary>
    public static class UiStyle
    {
        // ---------------------------------------------------------------- palette

        /// <summary>The one accent colour: rims, glows, primary buttons, titles' glow, badges.</summary>
        public static readonly Color Accent = new(0.55f, 0.88f, 1f);
        /// <summary>Near-white tint of the accent for crystal rims and highlights.</summary>
        public static readonly Color Rim = Color.Lerp(Accent, Color.white, 0.7f);
        public static readonly Color Text = Color.white;
        public static readonly Color TextDim = Color.Lerp(Accent, Color.white, 0.8f) * new Color(1f, 1f, 1f, 0.85f);
        /// <summary>Dark outline and shadow behind all text so it stays readable against a bright room.</summary>
        public static readonly Color TextOutline = new(0.02f, 0.06f, 0.12f, 1f);
        public static readonly Color TextShadow = new(0.02f, 0.06f, 0.12f, 0.6f);
        /// <summary>Crystal slab tint (alpha = how much it hides the room behind it).</summary>
        public static readonly Color CrystalTint = new(Accent.r * 0.2f, Accent.g * 0.32f, Accent.b * 0.42f, 0.55f);
        public static readonly Color P1 = new(1f, 0.3f, 0.28f);
        public static readonly Color P2 = new(0.3f, 0.55f, 1f);
        public static readonly Color Pointer = Rim;
        public static readonly Color Ash = new(0.35f, 0.35f, 0.4f);
        public static readonly Color[] Confetti = { Accent, Rim, Color.white };

        /// <summary>P1 red, P2 blue, anyone else white.</summary>
        public static Color PlayerColor(string playerId) => playerId switch
        {
            "P1" => P1,
            "P2" => P2,
            _ => Text,
        };

        /// <summary>"#RRGGBB" for TextMeshPro rich text colour tags.</summary>
        public static string Hex(Color color) => "#" + ColorUtility.ToHtmlStringRGB(color);

        public static Color WithAlpha(Color color, float alpha) => new(color.r, color.g, color.b, alpha);

        // ---------------------------------------------------------------- crystal surfaces

        /// <summary>How one <see cref="Crystal"/> surface looks. Sizes in metres.</summary>
        public struct CrystalStyle
        {
            public Color Fill;
            public Color Rim;
            public Color Glow;
            public Color Strip;
            public float Cut;
            public float RimWidth;
            public float Bevel;
            public float Highlight;
            public float Margin;
        }

        /// <summary>A menu or banner panel: accent strip on top, rim, glow and the highlight streak.</summary>
        public static CrystalStyle Panel => new()
        {
            Fill = CrystalTint, Rim = WithAlpha(Rim, 1f), Glow = WithAlpha(Accent, 0.45f), Strip = WithAlpha(Accent, 0.95f),
            Cut = 0.024f, RimWidth = 0.0024f, Bevel = 0.012f, Highlight = 0.22f, Margin = 0.035f,
        };

        /// <summary>A stat card or timer badge sitting on or near a panel: quieter, no strip.</summary>
        public static CrystalStyle Card => new()
        {
            Fill = WithAlpha(Color.Lerp(CrystalTint, Accent, 0.12f), 0.45f), Rim = WithAlpha(Rim, 0.4f), Glow = WithAlpha(Accent, 0f),
            Strip = Color.clear, Cut = 0.012f, RimWidth = 0.0016f, Bevel = 0.006f, Highlight = 0f, Margin = 0.006f,
        };

        /// <summary>Primary button: accent-filled crystal.</summary>
        public static CrystalStyle Primary => new()
        {
            Fill = WithAlpha(Accent * 0.55f, 0.8f), Rim = WithAlpha(Rim, 1f), Glow = WithAlpha(Accent, 0.3f), Strip = Color.clear,
            Cut = 0.014f, RimWidth = 0.002f, Bevel = 0.008f, Highlight = 0.3f, Margin = 0.02f,
        };

        /// <summary>Secondary button: a subtle outline on clear crystal.</summary>
        public static CrystalStyle Secondary => new()
        {
            Fill = WithAlpha(CrystalTint, 0.25f), Rim = WithAlpha(Accent, 0.5f), Glow = WithAlpha(Accent, 0f), Strip = Color.clear,
            Cut = 0.014f, RimWidth = 0.0016f, Bevel = 0.005f, Highlight = 0f, Margin = 0.02f,
        };

        /// <summary>Small floating readout (match timer): clear crystal with an accent rim and a little glow.</summary>
        public static CrystalStyle Hud => new()
        {
            Fill = CrystalTint, Rim = WithAlpha(Rim, 0.9f), Glow = WithAlpha(Accent, 0.3f), Strip = Color.clear,
            Cut = 0.014f, RimWidth = 0.002f, Bevel = 0.007f, Highlight = 0.15f, Margin = 0.02f,
        };

        /// <summary>Award pill: accent outline, faint accent fill.</summary>
        public static CrystalStyle Badge => new()
        {
            Fill = WithAlpha(Accent * 0.4f, 0.45f), Rim = WithAlpha(Accent, 0.95f), Glow = WithAlpha(Accent, 0.25f), Strip = Color.clear,
            Cut = 0.006f, RimWidth = 0.0014f, Bevel = 0.003f, Highlight = 0f, Margin = 0.006f,
        };

        /// <summary>Gaze dwell progress bar under a button label.</summary>
        public static CrystalStyle Bar => new()
        {
            Fill = WithAlpha(Rim, 1f), Rim = WithAlpha(Color.white, 1f), Glow = WithAlpha(Accent, 0.7f), Strip = Color.clear,
            Cut = 0.002f, RimWidth = 0.0008f, Bevel = 0.001f, Highlight = 0f, Margin = 0.008f,
        };

        /// <summary>A button (or any surface) while the pointer or gaze is on it: bright rim and a strong accent glow.</summary>
        public static CrystalStyle Hovered(CrystalStyle style)
        {
            style.Fill = WithAlpha(Color.Lerp(style.Fill, Accent, 0.35f), Mathf.Max(style.Fill.a, 0.6f));
            style.Rim = WithAlpha(Color.white, 1f);
            style.Glow = WithAlpha(Accent, 0.85f);
            style.Highlight = Mathf.Max(style.Highlight, 0.3f);
            return style;
        }

        /// <summary>Same surface, alarm state (e.g. last 10 s): blends rim and glow towards white with <paramref name="amount"/>.</summary>
        public static CrystalStyle Pulsing(CrystalStyle style, float amount)
        {
            style.Rim = Color.Lerp(style.Rim, Color.white, amount);
            style.Glow = WithAlpha(Accent, Mathf.Lerp(style.Glow.a, 0.9f, amount));
            style.Fill = Color.Lerp(style.Fill, WithAlpha(Accent * 0.5f, 0.8f), amount * 0.6f);
            return style;
        }

        /// <summary>A crystal quad plus its own material; resize or restyle it without rebuilding anything.</summary>
        public sealed class Crystal
        {
            private static readonly int FillId = Shader.PropertyToID("_FillColor");
            private static readonly int RimId = Shader.PropertyToID("_RimColor");
            private static readonly int GlowId = Shader.PropertyToID("_GlowColor");
            private static readonly int StripId = Shader.PropertyToID("_StripColor");
            private static readonly int RectId = Shader.PropertyToID("_Rect");
            private static readonly int FacetId = Shader.PropertyToID("_Facet");

            public Transform Transform { get; }
            public Material Material { get; }
            public Vector2 Size { get; private set; }
            public CrystalStyle Style { get; private set; }

            internal Crystal(Transform transform, Material material, Vector2 size, CrystalStyle style)
            {
                Transform = transform;
                Material = material;
                Apply(style, size);
            }

            public void Apply(CrystalStyle style) => Apply(style, Size);

            public void Resize(Vector2 size) => Apply(Style, size);

            public void Apply(CrystalStyle style, Vector2 size)
            {
                Style = style;
                Size = size;
                var margin = Mathf.Max(style.Margin, 0.001f);
                Transform.localScale = new Vector3(Mathf.Max(size.x, 1e-4f) + 2f * margin, Mathf.Max(size.y, 1e-4f) + 2f * margin, 1f);
                if (Material == null)
                    return;
                Material.SetColor(FillId, style.Fill);
                Material.SetColor(RimId, style.Rim);
                Material.SetColor(GlowId, style.Glow);
                Material.SetColor(StripId, style.Strip);
                Material.SetVector(RectId, new Vector4(size.x, size.y, style.Cut, margin));
                Material.SetVector(FacetId, new Vector4(style.RimWidth, style.Bevel, style.Highlight, 0.0045f));
            }
        }

        /// <summary>
        /// A crystal surface of <paramref name="size"/> centred at <paramref name="localPosition"/>. Its material is new;
        /// pass <paramref name="owned"/> to collect it so the owner can <see cref="DestroyAll"/> when it rebuilds.
        /// </summary>
        public static Crystal CreateCrystal(string name, Transform parent, Vector2 size, CrystalStyle style, Vector3 localPosition,
            int sortingOrder = SortPanel, List<Material> owned = null)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPosition;
            go.AddComponent<MeshFilter>().sharedMesh = QuadMesh;
            var renderer = go.AddComponent<MeshRenderer>();
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            renderer.sortingOrder = sortingOrder;
            var source = CrystalSource;
            var material = source != null ? new Material(source) : null;
            renderer.sharedMaterial = material;
            if (material != null)
                owned?.Add(material);
            return new Crystal(go.transform, material, size, style);
        }

        // ---------------------------------------------------------------- text

        /// <summary>
        /// Draw order for UI pieces that sit a few millimetres apart (transparent objects are otherwise sorted by distance
        /// to their centre, which puts an off-centre button behind its own panel).
        /// </summary>
        public const int SortPanel = 10;
        public const int SortSurface = 11;
        public const int SortBar = 12;
        public const int SortText = 13;

        /// <summary>
        /// World-space TextMeshPro label. <paramref name="size"/> is the em height in metres (a line is ~1.3 em in
        /// Rajdhani). Display = Rajdhani Bold (titles, buttons), otherwise SemiBold. Every label gets a dark outline;
        /// <paramref name="glow"/> swaps its dark shadow for a soft glow of that colour.
        /// </summary>
        public static TextMeshPro CreateText(string name, Transform parent, string text, Vector3 localPosition, float size, Color color,
            bool display = false, Color? glow = null, TextAlignmentOptions alignment = TextAlignmentOptions.Center,
            float width = 1.2f, float spacing = 0f)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPosition;
            var label = go.AddComponent<TextMeshPro>();
            var theme = Theme;
            var font = theme != null ? (display ? theme.DisplayFont : theme.BodyFont) : null;
            if (font != null)
            {
                label.font = font;
                label.fontSharedMaterial = TextMaterial(display, glow);
            }
            label.fontSize = size * 10f;
            label.rectTransform.sizeDelta = new Vector2(width, size * 1.5f);
            label.alignment = alignment;
            label.textWrappingMode = TextWrappingModes.NoWrap;
            label.overflowMode = TextOverflowModes.Overflow;
            label.richText = true;
            label.characterSpacing = spacing;
            label.color = color;
            label.text = text;
            label.sortingOrder = SortText;
            label.renderer.shadowCastingMode = ShadowCastingMode.Off;
            label.renderer.receiveShadows = false;
            return label;
        }

        /// <summary>Height in metres <paramref name="label"/> needs for its current text (lines × line height).</summary>
        public static float Height(TextMeshPro label) =>
            string.IsNullOrEmpty(label.text) ? 0f : label.GetPreferredValues(label.text).y;

        /// <summary>Width in metres of <paramref name="label"/>'s current text.</summary>
        public static float Width(TextMeshPro label) =>
            string.IsNullOrEmpty(label.text) ? 0f : label.GetPreferredValues(label.text).x;

        /// <summary>Destroys materials collected by <see cref="CreateCrystal"/> and clears the list.</summary>
        public static void DestroyAll(List<Material> materials)
        {
            foreach (var material in materials)
                if (material != null)
                    Object.Destroy(material);
            materials.Clear();
        }

        // ---------------------------------------------------------------- resources

        private static readonly int OutlineColorId = Shader.PropertyToID("_OutlineColor");
        private static readonly int UnderlayColorId = Shader.PropertyToID("_UnderlayColor");
        private static readonly int UnderlaySoftnessId = Shader.PropertyToID("_UnderlaySoftness");
        private static readonly int UnderlayDilateId = Shader.PropertyToID("_UnderlayDilate");

        private static UiTheme _theme;
        private static bool _warned;
        private static Mesh _quadMesh;
        private static readonly Dictionary<(bool Display, Color32 Glow, bool HasGlow), Material> TextMaterials = new();

        public static UiTheme Theme
        {
            get
            {
                if (_theme != null)
                    return _theme;
                _theme = Resources.Load<UiTheme>(UiTheme.ResourceName);
                if (_theme == null && !_warned)
                {
                    _warned = true;
                    Debug.LogError($"[SpellGame] UI theme '{UiTheme.ResourceName}' not found in Resources; run SpellGame → Rebuild Main Scene.");
                }
                return _theme;
            }
        }

        private static Material CrystalSource
        {
            get
            {
                var theme = Theme;
                return theme != null ? theme.Crystal : null;
            }
        }

        /// <summary>Shared per colour: a copy of the theme's font material with the glow (or dark shadow) colour set.</summary>
        private static Material TextMaterial(bool display, Color? glow)
        {
            var key = (display, (Color32)(glow ?? Color.clear), glow.HasValue);
            if (TextMaterials.TryGetValue(key, out var cached) && cached != null)
                return cached;

            var theme = Theme;
            var source = display ? theme.DisplayMaterial : theme.BodyMaterial;
            if (source == null)
                source = (display ? theme.DisplayFont : theme.BodyFont).material;
            var material = new Material(source) { name = $"{source.name} {(glow.HasValue ? Hex(glow.Value) : "shadow")}" };
            material.SetColor(OutlineColorId, TextOutline);
            material.SetColor(UnderlayColorId, glow.HasValue ? WithAlpha(glow.Value, 0.75f) : TextShadow);
            material.SetFloat(UnderlaySoftnessId, glow.HasValue ? 0.8f : 0.45f);
            material.SetFloat(UnderlayDilateId, glow.HasValue ? 0.6f : 0.3f);
            TextMaterials[key] = material;
            return material;
        }

        private static Mesh QuadMesh
        {
            get
            {
                if (_quadMesh != null)
                    return _quadMesh;
                var primitive = GameObject.CreatePrimitive(PrimitiveType.Quad);
                _quadMesh = primitive.GetComponent<MeshFilter>().sharedMesh;
                Object.Destroy(primitive);
                return _quadMesh;
            }
        }
    }
}
